	ADD COLUMN `RESIDUE_AMT_CNY` DECIMAL(30,9) NULL DEFAULT NULL COMMENT '折人民币产品剩余金额：产品剩余份额乘以当期净值乘以汇率' ;
ALTER TABLE `chb_prd_position`
	ADD COLUMN `NET_VALUE` DECIMAL(15,9) NULL DEFAULT NULL COMMENT '当期净值：产品当日最近有效净值' ;
ALTER TABLE `chb_prd_position`
	ADD COLUMN `RATE_VALUE` DECIMAL(15,9) NULL DEFAULT NULL COMMENT '当期汇率：当日最近有效汇率' ;

